ype\":\"container\",\"settings\":{\"flex_direction\":\"column\"},\"elements\":[{\"id\":\"3d123f1\",\"elType\":\"widget\",\"settings\":{\"title\":\"Top Selling Product\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Noto Sans Bengali\",\"typography_font_size\":{\"unit\":\"px\",\"size\":28,\"sizes\":[]},\"typography_font_weight\":\"600\",\"_flex_align_self\":\"center\"},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"aa02974\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\"},\"elements\":[{\"id\":\"159e711\",\"elType\":\"widget\",\"settings\":{\"shortcode\":\"[custom_grid ids=\\\"94, 92, 90, 88\\\"]\",\"custom_css\":\"\\r\\n    @import url(\'https:\\/\\/fonts.googleapis.com\\/css2?family=Open+Sans:wght@400;600;700&display=swap\');\\r\\n\\r\\n    .custom-product-grid {\\r\\n        display: grid;\\r\\n        grid-template-columns: repeat(2, 1fr); \\/* PC \\u09a4\\u09c7 \\u09e8\\u099f\\u09be \\u0995\\u09b2\\u09be\\u09ae *\\/\\r\\n        gap: 25px;\\r\\n        font-family: \'Open Sans\', sans-serif;\\r\\n        padding: 20px 0;\\r\\n    }\\r\\n\\r\\n    .product-card {\\r\\n        display: flex;\\r\\n        position: relative;\\r\\n        background: #fff;\\r\\n        border: 1px solid #f2f2f2;\\r\\n        border-radius: 12px;\\r\\n        overflow: hidden;\\r\\n        height: 100%;\\r\\n        transition: 0.3s ease;\\r\\n    }\\r\\n\\r\\n    \\/* Best Selling Badge - \\u098f\\u0995\\u09a6\\u09ae \\u0995\\u09cb\\u09a3\\u09be\\u09af\\u09bc \\u09b2\\u09be\\u0997\\u09be\\u09a8\\u09cb *\\/\\r\\n    .best-selling-badge {\\r\\n        position: absolute;\\r\\n        top: 0;\\r\\n        right: 0;\\r\\n        background: #ff4d4d;\\r\\n        color: #fff;\\r\\n        font-size: 11px;\\r\\n        padding: 5px 12px;\\r\\n        border-bottom-left-radius: 12px;\\r\\n        font-weight: bold;\\r\\n        z-index: 10;\\r\\n        display: flex;\\r\\n        align-items: center;\\r\\n        gap: 5px;\\r\\n    }\\r\\n\\r\\n    .product-image {\\r\\n        flex: 1;\\r\\n        background: #fff;\\r\\n        padding: 10px;\\r\\n    }\\r\\n\\r\\n    .product-image img {\\r\\n        width: 100%;\\r\\n        height: 100%;\\r\\n        object-fit: contain;\\r\\n    }\\r\\n\\r\\n    .product-info {\\r\\n        flex: 1.2;\\r\\n        padding: 30px 20px;\\r\\n        display: flex;\\r\\n        flex-direction: column;\\r\\n        justify-content: center;\\r\\n    }\\r\\n\\r\\n    .product-title a {\\r\\n        font-size: 18px;\\r\\n        color: #0d233e;\\r\\n        text-decoration: none;\\r\\n        font-weight: 700;\\r\\n        margin-bottom: 8px;\\r\\n        display: block;\\r\\n    }\\r\\n\\r\\n    .product-price {\\r\\n        font-size: 20px;\\r\\n        color: #F48721 ;\\r\\n        font-weight: 700;\\r\\n        margin-bottom: 25px;\\r\\n    }\\r\\n\\r\\n    .product-price del {\\r\\n        color: #999;\\r\\n        font-size: 15px;\\r\\n        font-weight: 400;\\r\\n        margin-right: 8px;\\r\\n    }\\r\\n\\r\\n    .product-buttons {\\r\\n        display: flex;\\r\\n        gap: 12px;\\r\\n    }\\r\\n\\r\\n    \\/* Button Base Style *\\/\\r\\n    .btn-add-to-cart, .btn-buy-now {\\r\\n        flex: 1;\\r\\n        padding: 10px 5px;\\r\\n        border-radius: 3px;\\r\\n        text-decoration: none;\\r\\n        font-size: 14px;\\r\\n        font-weight: 600;\\r\\n        display: flex;\\r\\n        align-items: center;\\r\\n        justify-content: center;\\r\\n        gap: 8px;\\r\\n        border: 1.5px solid #F48721 ;\\r\\n        transition: all 0.3s ease;\\r\\n    }\\r\\n\\r\\n    \\/*--- Add to Cart Button Style ---*\\/\\r\\n    .btn-add-to-cart { \\r\\n        background: transparent; \\r\\n        color: #F48721 ; \\r\\n    }\\r\\n    \\r\\n    \\/* Add to Cart Hover *\\/\\r\\n    .btn-add-to-cart:hover {\\r\\n        background: #F48721 ;\\r\\n        color: #fff;\\r\\n        border-color: #F48721 ;\\r\\n    }\\r\\n\\r\\n    \\/*--- Buy Now Button Style ---*\\/\\r\\n    .btn-buy-now { \\r\\n        background: #F48721 ; \\r\\n        color: #fff; \\r\\n    }\\r\\n\\r\\n    \\/* Buy Now Hover *\\/\\r\\n    .btn-buy-now:hover {\\r\\n        background: #041F1E; \\/* \\u098f\\u0995\\u099f\\u09c1 \\u0997\\u09be\\u09dd \\u0985\\u09b0\\u09c7\\u099e\\u09cd\\u099c *\\/\\r\\n        border-color: #041F1E;\\r\\n        color: #fff\\r\\n    }\\r\\n\\r\\n    \\/* Tablet Responsive (\\u099f\\u09cd\\u09af\\u09be\\u09ac\\u09c7 \\u09e7\\u099f\\u09be \\u0995\\u09b2\\u09be\\u09ae) *\\/\\r\\n    @media (min-width: 768px) and (max-width: 1024px) {\\r\\n        .custom-product-grid {\\r\\n            grid-template-columns: repeat(1, 1fr);\\r\\n        }\\r\\n    }\\r\\n\\r\\n    \\/* Mobile Responsive (\\u09ae\\u09cb\\u09ac\\u09be\\u0987\\u09b2\\u09c7 \\u09e8\\u099f\\u09be \\u0995\\u09b2\\u09be\\u09ae + Buy Now \\u09b9\\u09be\\u0987\\u09a1) *\\/\\r\\n    @media (max-width: 767px) {\\r\\n        .custom-product-grid {\\r\\n            grid-template-columns: repeat(2, 1fr);\\r\\n            gap: 12px;\\r\\n        }\\r\\n\\r\\n        .product-card {\\r\\n            flex-direction: column; \\r\\n        }\\r\\n\\r\\n        .product-image {\\r\\n            max-width: 100%;\\r\\n            height: 150px;\\r\\n        }\\r\\n\\r\\n        .product-info {\\r\\n            padding: 15px 10px;\\r\\n            text-align: left;\\r\\n        }\\r\\n\\r\\n        .product-title a { font-size: 14px; }\\r\\n        .product-price { font-size: 16px; margin-bottom: 15px; }\\r\\n\\r\\n        \\/* \\u09ae\\u09cb\\u09ac\\u09be\\u0987\\u09b2\\u09c7 Buy Now \\u09ac\\u09be\\u099f\\u09a8\\u099f\\u09bf \\u09b9\\u09be\\u0987\\u09a1 *\\/\\r\\n        .btn-buy-now {\\r\\n            display: none !important;\\r\\n        }\\r\\n\\r\\n        .product-buttons {\\r\\n            flex-direction: column;\\r\\n        }\\r\\n        \\r\\n        .btn-add-to-cart, .btn-buy-now {\\r\\n            padding: 6px 5px !important;\\r\\n            \\r\\n            