\"isInner\":true},{\"id\":\"4314e31\",\"elType\":\"container\",\"settings\":{\"flex_direction\":\"column\",\"content_width\":\"full\",\"width\":{\"unit\":\"%\",\"size\":\"50\"},\"__globals__\":{\"background_color\":\"\"}},\"elements\":[{\"id\":\"65481e6\",\"elType\":\"widget\",\"settings\":{\"__dynamic__\":{\"title\":\"[elementor-tag id=\\\"\\\" name=\\\"woocommerce-product-title-tag\\\" settings=\\\"%7B%22product_id%22%3Afalse%2C%22before%22%3A%22%22%2C%22after%22%3A%22%22%2C%22fallback%22%3A%22%22%7D\\\"]\"},\"title\":\"Add Your Heading Text Here\",\"align\":\"start\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Noto Sans Bengali\",\"typography_font_size\":{\"unit\":\"px\",\"size\":24,\"sizes\":[]},\"typography_font_weight\":\"600\",\"text_stroke_text_stroke\":{\"unit\":\"px\",\"size\":0,\"sizes\":[]},\"_margin\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_padding\":{\"unit\":\"px\",\"top\":\"0\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false},\"_flex_align_self\":\"flex-start\",\"_flex_order\":\"start\"},\"elements\":[],\"widgetType\":\"woocommerce-product-title\"},{\"id\":\"2620e69\",\"elType\":\"widget\",\"settings\":{\"price_color\":\"#FF0000\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Noto Sans Bengali\",\"typography_font_size\":{\"unit\":\"px\",\"size\":13,\"sizes\":[]},\"typography_font_weight\":\"600\",\"_flex_align_self_mobile\":\"flex-start\",\"__globals__\":{\"sale_price_color\":\"globals\\/colors?id=astglobalcolor0\"}},\"elements\":[],\"widgetType\":\"woocommerce-product-price\"},{\"id\":\"669dc5c\",\"elType\":\"widget\",\"settings\":{\"html\":\"<div class=\\\"gb-professional-container\\\">\\r\\n    <!-- Quantity Section -->\\r\\n    <div class=\\\"gb-qty-row\\\">\\r\\n        <label class=\\\"gb-qty-label\\\">Quantity:<\\/label>\\r\\n        <div class=\\\"gb-qty-box-wrapper\\\">\\r\\n            <div class=\\\"gb-qty-box\\\">\\r\\n                <button type=\\\"button\\\" class=\\\"gb-qty-btn\\\" id=\\\"minus-btn\\\">\\u2212<\\/button>\\r\\n                <input type=\\\"number\\\" id=\\\"gb-quantity\\\" class=\\\"gb-qty-input\\\" value=\\\"1\\\" min=\\\"1\\\" inputmode=\\\"numeric\\\">\\r\\n                <button type=\\\"button\\\" class=\\\"gb-qty-btn\\\" id=\\\"plus-btn\\\">+<\\/button>\\r\\n            <\\/div>\\r\\n        <\\/div>\\r\\n    <\\/div>\\r\\n\\r\\n    <!-- Dual Buttons Section -->\\r\\n    <div class=\\\"gb-btn-group\\\">\\r\\n        <button type=\\\"button\\\" class=\\\"gb-btn gb-atc-btn\\\" onclick=\\\"handleCartAction(\'add\')\\\">\\r\\n            <i class=\\\"fas fa-shopping-bag\\\"><\\/i> ADD TO CART\\r\\n        <\\/button>\\r\\n        <button type=\\\"button\\\" class=\\\"gb-btn gb-buy-btn\\\" onclick=\\\"handleCartAction(\'buy\')\\\">\\r\\n            BUY NOW\\r\\n        <\\/button>\\r\\n    <\\/div>\\r\\n<\\/div>\\r\\n\\r\\n<style>\\r\\n@import url(\'https:\\/\\/fonts.googleapis.com\\/css2?family=Open+Sans:wght@400;600;700&display=swap\');\\r\\n\\r\\n.gb-professional-container {\\r\\n    font-family: \'Open Sans\', sans-serif;\\r\\n    width: 100%;\\r\\n    max-width: 100%; \\r\\n    display: flex;\\r\\n    flex-direction: column;\\r\\n    gap: 15px;\\r\\n}\\r\\n\\r\\n\\/* Quantity Section *\\/\\r\\n.gb-qty-row {\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    width:900%;\\r\\n}\\r\\n\\r\\n.gb-qty-label {\\r\\n    font-size: 16px;\\r\\n    color: #444;\\r\\n    font-weight: 400;\\r\\n    margin-right: 15px;\\r\\n}\\r\\n\\r\\n.gb-qty-box {\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    border: 1px solid #e2e2e2;\\r\\n    border-radius: 6px;\\r\\n    padding: 3px 6px;\\r\\n    background: #fff;\\r\\n    width: 200px; \\r\\n    justify-content: space-between;\\r\\n}\\r\\n\\r\\n.gb-qty-btn {\\r\\n    width: 8px;\\r\\n    height: 8px;\\r\\n    border-radius:%;\\r\\n    border: none;\\r\\n    background-color: #f1f3f5;\\r\\n    color: #555;\\r\\n    font-size: 16px;\\r\\n    cursor: pointer;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: center;\\r\\n}\\r\\n\\r\\n.gb-qty-input {\\r\\n    width: 40px;\\r\\n    text-align: center;\\r\\n    border: none !important;\\r\\n    outline: none !important;\\r\\n    font-size: 16px;\\r\\n    font-weight: 600;\\r\\n    color: #333;\\r\\n    background: transparent;\\r\\n}\\r\\n\\r\\n\\/* Button Group Layout (50% \\/ 50%) *\\/\\r\\n.gb-btn-group {\\r\\n    display: flex;\\r\\n    gap: 15px;\\r\\n    width: 100%;\\r\\n}\\r\\n\\r\\n.gb-btn {\\r\\n    flex: 1; \\r\\n    border: none;\\r\\n    padding: 12px 0;\\r\\n    font-size: 14px;\\r\\n    font-weight: 700;\\r\\n    border-radius: 6px;\\r\\n    cursor: pointer;\\r\\n    display: flex;\\r\\n    align-items: center;\\r\\n    justify-content: center;\\r\\n    gap: 8px;\\r\\n    text-transform: uppercase;\\r\\n}\\r\\n\\r\\n.gb-atc-btn {\\r\\n    background-color: #ff8a1e; \\r\\n    color: #fff;\\r\\n}\\r\\n\\r\\n.gb-buy-btn {\\r\\n    background-color: #031d1a; \\r\\n    color: #fff;\\r\\n}\\r\\n\\r\\n\\/* Remove Input Arrows *\\/\\r\\n.gb-qty-input::-webkit-outer-spin-button,\\r\\n.gb-qty-input::-webkit-inner-spin-button {\\r\\n    -webkit-appearance: none;\\r\\n    margin: 0;\\r\\n}\\r\\n\\r\\n\\/* --- Responsive Layout --- *\\/\\r\\n@media (max-width: 480px) {\\r\\n    .gb-qty-box {\\r\\n        width: 70%; \\r\\n    }\\r\\n    \\r\\n    .gb-btn {\\r\\n        font-size: 13px; \\r\\n         padding: 10px 0 !important;\\r\\n         border-radius: 5px !important;\\r\\n    }\\r\\n    \\r\\n   \\r\\n    \\r\\n}\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\/* --- Energetic Pulse + Vibration for Buy Now --- *\\/\\r\\n.gb-buy-btn {\\r\\n    animation: gb-vibrant-pulse 2s infinite; \\/* 2 second cycle *\\/\\r\\n    box-shadow: 0 0 0 0 rgba(3, 29, 26, 0.7);\\r\\n    display: inline-flex;\\r\\n}\\r\\n\\r\\n@keyframes gb-vibrant-pulse {\\r\\n    \\/* Shurute ektu kapa-kapi (Vibration) *\\/\\r\\n    0% { transform: scale(0.98) translateX(0); }\\r\\n    5% { transform: scale(1) translateX(-2px) rotate(-1deg); }\\r\\n    10% { transform: scale(1) translateX(2px) rotate(1deg); }\\r\\n    15% { transform: scale(1) translateX(-2px) rotate(-1deg); }\\r\\n    20% { transform: scale(1) translateX(2px) rotate(1deg); }\\r\\n    25% { transform: scale(1) translateX(0) rotate(0); }\\r\\n\\r\\n    \\/* Tarpor boro hoye Pulse wave ber hobe *\\/\\r\\n    70% {\\r\\n        transform: scale(1.05); \\/* Ektu beshi boro hobe jate chokhe pore *\\/\\r\\n        box-shadow: 0 0 0 15px rgba(3, 29, 26, 0); \\/* Boro wave *\\/\\r\\n    }\\r\\n    \\r\\n    \\/* Shob sheshe abr purbo abosthay fire jabe *\\/\\r\\n    100% {\\r\\n        transform: scale(0.98);\\r\\n        box-shadow: 0 0 0 0 rgba(3, 29, 26, 0);\\r\\n    }\\r\\n}\\r\\n\\r\\n<\\/style>\\r\\n\\r\\n<script>\\r\\ndocument.addEventListener(\'DOMContentLoaded\', function() {\\r\\n    const qtyInput = document.getElementById(\'gb-quantity\');\\r\\n    const minusBtn = document.getElementById(\'minus-btn\');\\r\\n    const plusBtn = document.getElementById(\'plus-btn\');\\r\\n\\r\\n    minusBtn.addEventListener(\'click\', () => {\\r\\n        let val = parseInt(qtyInput.value);\\r\\n        if (val > 1) qtyInput.value = val - 1;\\r\\n    });\\r\\n\\r\\n    plusBtn.addEventListener(\'click\', () => {\\r\\n        let val = parseInt(qtyInput.value);\\r\\n        qtyInput.value = val + 1;\\r\\n    });\\r\\n});\\r\\n\\r\\nfunction handleCartAction(action) {\\r\\n    const qty = document.getElementById(\'gb-quantity\').value;\\r\\n    const productId = document.querySelector(\'.single_add_to_cart_button\')?.value || \\r\\n                     document.body.className.match(\\/postid-(\\\\d+)\\/)?.[1];\\r\\n\\r\\n    if (!productId) {\\r\\n        alert(\\\"Product ID not found.\\\");\\r\\n        return;\\r\\n    }\\r\\n\\r\\n    if (action === \'add\') {\\r\\n        \\/\\/ AJAX Add to Cart Logic (No Reload)\\r\\n        const formData = new FormData();\\r\\n        formData.append(\'action\', \'woocommerce_add_to_cart\');\\r\\n        formData.append(\'product_id\', productId);\\r\\n        formData.append(\'quantity\', qty);\\r\\n\\r\\n        \\/\\/ UI feedback start\\r\\n        const atcBtn = document.querySelector(\'.gb-atc-btn\');\\r\\n        const originalText = atcBtn.innerHTML;\\r\\n        atcBtn.innerText = \\\"Adding...\\\";\\r\\n        atcBtn.disabled = true;\\r\\n\\r\\n        fetch(window.location.origin + \'\\/?wc-ajax=add_to_cart\', {\\r\\n            method: \'POST\',\\r\\n            body: formData\\r\\n        })\\r\\n        .then(response => response.json())\\r\\n        .then(data => {\\r\\n            if (data.error && data.product_url) {\\r\\n                window.location.href = data.product_url;\\r\\n                return;\\r\\n            }\\r\\n            \\/\\/ Update fragments (Cart widget update)\\r\\n            jQuery(document.body).trigger(\'added_to_cart\', [data.fragments, data.cart_hash]);\\r\\n            \\r\\n            \\/\\/ UI feedback reset\\r\\n            atcBtn.innerHTML = \\\"\\u2713 Added\\\";\\r\\n            setTimeout(() => {\\r\\n                atcBtn.innerHTML = originalText;\\r\\n                atcBtn.disabled = false;\\r\\n            }, 2000);\\r\\n        })\\r\\n        .catch(error => {\\r\\n            console.error(\'Error:\', error);\\r\\n            atcBtn.innerHTML = originalText;\\r\\n            atcBtn.disabled = false;\\r\\n        });\\r\\n\\r\\n    } else if (action === \'buy\') {\\r\\n        \\/\\/ Buy Now: Add to cart and go to checkout\\r\\n        window.location.href = `${window.location.origin}\\/checkout\\/?add-to-cart=${productId}&quantity=${qty}`;\\r\\n    }\\r\\n}\\r\\n<\\/script>\\r\\n\"},\"elements\":[],\"widgetType\":\"html\"},{\"id\":\"d7a8455\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"flex_direction\":\"row\"},\"elements\":[{\"id\":\"d5ec790\",\"elType\":\"widge