    .custom-product-grid {\\r\\n        display: grid;\\r\\n        grid-template-columns: repeat(2, 1fr); \\/* PC \\u09a4\\u09c7 \\u09e8\\u099f\\u09be \\u0995\\u09b2\\u09be\\u09ae *\\/\\r\\n        gap: 25px;\\r\\n        font-family: \'Open Sans\', sans-serif;\\r\\n        padding: 20px 0;\\r\\n    }\\r\\n\\r\\n    .product-card {\\r\\n        display: flex;\\r\\n        position: relative;\\r\\n        background: #fff;\\r\\n        border: 1px solid #f2f2f2;\\r\\n        border-radius: 12px;\\r\\n        overflow: hidden;\\r\\n        height: 100%;\\r\\n        transition: 0.3s ease;\\r\\n    }\\r\\n\\r\\n    \\/* Best Selling Badge - \\u098f\\u0995\\u09a6\\u09ae \\u0995\\u09cb\\u09a3\\u09be\\u09af\\u09bc \\u09b2\\u09be\\u0997\\u09be\\u09a8\\u09cb *\\/\\r\\n    .best-selling-badge {\\r\\n        position: absolute;\\r\\n        top: 0;\\r\\n        right: 0;\\r\\n        background: #ff4d4d;\\r\\n        color: #fff;\\r\\n        font-size: 11px;\\r\\n        padding: 5px 12px;\\r\\n        border-bottom-left-radius: 12px;\\r\\n        font-weight: bold;\\r\\n        z-index: 10;\\r\\n        display: flex;\\r\\n        align-items: center;\\r\\n        gap: 5px;\\r\\n    }\\r\\n\\r\\n    .product-image {\\r\\n        flex: 1;\\r\\n        background: #fff;\\r\\n        padding: 10px;\\r\\n    }\\r\\n\\r\\n    .product-image img {\\r\\n        width: 100%;\\r\\n        height: 100%;\\r\\n        object-fit: contain;\\r\\n    }\\r\\n\\r\\n    .product-info {\\r\\n        flex: 1.2;\\r\\n        padding: 30px 20px;\\r\\n        display: flex;\\r\\n        flex-direction: column;\\r\\n        justify-content: center;\\r\\n    }\\r\\n\\r\\n    .product-title a {\\r\\n        font-size: 18px;\\r\\n        color: #0d233e;\\r\\n        text-decoration: none;\\r\\n        font-weight: 700;\\r\\n        margin-bottom: 8px;\\r\\n        display: block;\\r\\n    }\\r\\n\\r\\n    .product-price {\\r\\n        font-size: 20px;\\r\\n        color: #F48721 ;\\r\\n        font-