board\r\n    remove_meta_box(\'dashboard_recent_comments\', \'dashboard\', \'normal\');\r\n\r\n    // Disable support for comments and trackbacks in post types\r\n    foreach (get_post_types() as $post_type) {\r\n        if (post_type_supports($post_type, \'comments\')) {\r\n            remove_post_type_support($post_type, \'comments\');\r\n            remove_post_type_support($post_type, \'trackbacks\');\r\n        }\r\n    }\r\n});\r\n\r\n// Close comments on the front-end\r\nadd_filter(\'comments_open\', \'__return_false\', 20, 2);\r\nadd_filter(\'pings_open\', \'__return_false\', 20, 2);\r\n\r\n// Hide existing comments\r\nadd_filter(\'comments_array\', \'__return_empty_array\', 10, 2);\r\n\r\n// Remove comments page in menu\r\nadd_action(\'admin_menu\', function () {\r\n    remove_menu_page(\'edit-comments.php\');\r\n});\r\n\r\n// Remove comments links from admin bar\r\nadd_action(\'init\', function () {\r\n    if (is_admin_bar_showing()) {\r\n        remove_action(\'admin_bar_menu\', \'wp_admin_bar_comments_menu\', 60);\r\n    }\r\n});','Completely Disable Comments','','draft','closed','closed','','','','','2026-05-04 12:26:45','0000-00-00 00:00:00','',0,'http://localhost/well-known/?post_type=wpcode&p=336',0,'wpcode','',0),(337,1,'2026-05-04 12:27:45','2026-05-04 12:27:45','\r\nfunction custom_woo_manual_grid($atts) {\r\n    // শর্টকোড অ্যাট্রিবিউট সেট করা (ডিফল্ট আইডি খালি থাকবে)\r\n    $atts = shortcode_atts(array(\r\n        \'ids\' => \'\', \r\n    ), $atts);\r\n\r\n    $args = array(\r\n        \'post_type\'      => \'product\',\r\n        \'posts_per_page\' => -1,\r\n    );\r\n\r\n    // যদি ইউজার আইডি দেয়, তবে শুধু সেই প্রোডাক্টগুলো আসবে\r\n    if (!empty($atts[\'ids\'])) {\r\n        $product_ids = explode(\',\', $atts[\'ids\']);\r\n        $args[\'post__in\'] = $product_ids;\r\n        $args[\'orderby\'] = \'post__in\'; // যেভাবে আইডি দিবে সেভাবেই সাজানো থাকবে\r\n    } else {\r\n        // আইডি না দিলে ডিফল্টভাবে বেস্ট সেলিং দেখাবে\r\n        $args[\'posts_per_page\'] = 8;\r\n        $args[\'meta_key\'] = \'total_sales\';\r\n        $args[\'orderby\'] = \'meta_value_num\';\r\n    }\r\n    \r\n    $loop = new WP_Query($args);\r\n    \r\n    ob_start();\r\n    if ($loop->have_posts()) :\r\n        echo \'<div class=\"custom-product-grid\">\';\r\n        while ($loop->have_posts()) : $loop->the_post();\r\n            global $product;\r\n            $product_id = get_the_ID();\r\n            $title = get_the_title();\r\n            $image = wp_get_attachment_image_src(get_post_thumbnail_id($product_id), \'large\')[0];\r\n            $price = $product->get_price_html();\r\n            $permalink = get_permalink($product_id);\r\n            $checkout_url = wc_get_checkout_url() . \'?add-to-cart=\' . $product_id;\r\n\r\n            $is_variable = $product->is_type(\'variable\');\r\n            $cart_url = $is_variable ? $permalink : esc_url($product->add_to_cart_url());\r\n            ?>\r\n\r\n            <div class=\"product-card\">\r\n                <div class=\"best-selling-badge\"><i class=\"fas fa-fire\"></i> Best Selling</div>\r\n                <div class=\"product-image\">\r\n                    <a href=\"<?php echo $permalink; ?>\">\r\n                        <img src=\"<?php echo $image; ?>\" alt=\"<?php echo $title; ?>\">\r\n                    </a>\r\n                </div>\r\n                <div class=\"product-info\">\r\n                    <h3 class=\"product-title\"><a href=\"<?php echo $permalink; ?>\"><?php echo $title; ?></a></h3>\r\n                    <div class=\"product-price\"><?php echo $price; ?></div>\r\n                    <div class=\"product-buttons\">\r\n                        <a href=\"<?php echo $cart_url; ?>\" class=\"btn-add-to-cart\">\r\n                            <i class=\"fas fa-shopping-cart\"></i> Add To Cart\r\n                        </a>\r\n                        <a href=\"<?php echo $checkout_url; ?>\" class=\"btn-buy-now\">\r\n                           <i class=\"fa